entity Prob_5_38a_vhdl is
	port (x_in, clock, reset_b: in bit);
end Prob_5_38a_vhdl;
architecture Behavioral of Prob_5_38a_vhdl is  constant s0: bit_vector (1 downto 0) := "00";  constant s1: bit_vector (1 downto 0) := "01";  constant s2: bit_vector (1 downto 0) := "10";  constant s3: bit_vector (1 downto 0) := "11";  signal state, next_state: bit_vector (1 downto 0);begin  process (clock, reset_b) begin    if (reset_b = '0') then state <= s0;    else state <= next_state; end if;  end process;  process (state, x_in) begin    next_state <= s0;    case (state) is      when s0 =>	if x_in = '0' then next_state <= s0; 						elsif x_in = '1' then next_state <= s3; end if;      when s1 =>	if x_in = '0' then next_state <= s1; 						elsif x_in = '1' then next_state <= s2; end if;      when s2 =>	if x_in = '0' then next_state <= s2; 						elsif x_in = '1' then next_state <= s0;  end if;      when s3 =>	if x_in = '0' then next_state <= s3; 						elsif x_in = '1' then next_state <= s1; end if;        when others  =>	next_state <= s0;    end case;  end process;end Behavioral;